def solve(intervals):
    if not intervals:
        return []

    # Union-Find (Disjoint Set Union) data structure
    parent = {}

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            parent[rootY] = rootX

    # Create a mapping from positions to unique identifiers
    positions = set()
    for start, end in intervals:
        positions.update([start, end])
    # Assign unique IDs to each position
    pos_to_id = {pos: i for i, pos in enumerate(sorted(positions))}
    num_positions = len(positions)

    # Initialize parent for each position
    for pos in positions:
        parent[pos] = pos

    # For each interval, connect its start and end
    for start, end in intervals:
        union(start, end)

    # Group all positions by their root
    groups = {}
    for pos in positions:
        root = find(pos)
        if root not in groups:
            groups[root] = []
        groups[root].append(pos)

    # Sort each group and extract merged intervals
    merged = []
    for group in groups.values():
        group.sort()
        merged_start = group[0]
        merged_end = group[-1]
        merged.append([merged_start, merged_end])

    # Sort the merged intervals by their start
    merged.sort()
    return merged

